t> <g fill="#FEF3C7" font-family="sans-serif" font-size="13" font-weight="700"> <text x="114" y="88" text-anchor="middle">1</text> <text x="182" y="88" text-anchor="middle">1</text> <polygon points="246,77 254,77 250,91" fill="#FDE68A"></polygon> <text x="114" y="116" text-anchor="middle">2</text> <text x="182" y="116" text-anchor="middle">4</text> <g fill="#FDE68A"> <polygon points="234,105 241,105 237.5,118"></polygon> <polygon points="243,105 250,105 246.5,118"></polygon> <polygon points="252,105 259,105 255.5,118"></polygon> <polygon points="261,105 268,105 264.5,118"></polygon> </g> <text x="114" y="144" text-anchor="middle">3</text> <text x="182" y="144" text-anchor="middle">9</text> <g fill="#FDE68A"> <polygon points="236,133 243,133 239.5,144"></polygon> <polygon points="246,133 253,133 249.5,144"></polygon> <polygon points="256,133 263,133 259.5,144"></polygon> <polygon points="231,146 266,143 266,149"></polygon> </g> <text x="114" y="172" text-anchor="middle">4</text> <text x="182" y="172" text-anchor="middle">16</text> <g fill="#FDE68A"> <polygon points="234,167 244,160 244,174"></polygon> <polygon points="249,161 255,161 252,174"></polygon> <polygon points="257,161 263,161 260,174"></polygon> <polygon points="265,161 271,161 268,174"></polygon> </g> </g> <line x1="78" y1="96" x2="282" y2="96" stroke="#FEF3C7" stroke-width="0.8" opacity="0.35"></line> <line x1="78" y1="124" x2="282" y2="124" stroke="#FEF3C7" stroke-width="0.8" opacity="0.35"></line> <line x1="78" y1="152" x2="282" y2="152" stroke="#FEF3C7" stroke-width="0.8" opacity="0.35"></line> </svg> <span class="lt-zoom-badge">Ampliar</span></div>
<figcaption class="lt-figcaption"><strong>Tablilla babilónica:</strong> correspondencia tabular entre números y sus cuadrados grabada en arcilla.</figcaption>
