<script>
  (function () {
    const root = document.getElementById("lt-funciones-exe");
    if (!root) return;

    const timelineItems = Array.from(root.querySelectorAll(".lt-item"));
    const filterButtons = Array.from(root.querySelectorAll(".lt-btn[data-filter]"));
    const expandAllBtn = root.querySelector("#ltExpandAllBtn");
    const collapseAllBtn = root.querySelector("#ltCollapseAllBtn");
    const statusCounter = root.querySelector("#ltStatusCounter");

    const lightbox = root.querySelector("#ltLightbox");
    const lightboxTitle = root.querySelector("#ltLightboxTitle");
    const lightboxMedia = root.querySelector("#ltLightboxMedia");
    const lightboxCaption = root.querySelector("#ltLightboxCaption");
    const lightboxClose = root.querySelector("#ltLightboxClose");

    let lastFocused = null;

    /* Helper de accesibilidad para controles div[role="button"] (clic + Enter/Espacio) */
    function bindAccessibleClick(el, handler) {
      if (!el) return;
      el.addEventListener("click", handler);
      el.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          handler(event);
        }
      });
    }

    /* 1. Despliegue individual de tarjetas (contraídas por defecto) */
    timelineItems.forEach((item) => {
      const trigger = item.querySelector(".lt-card-trigger");
      bindAccessibleClick(trigger, () => {
        const isOpen = item.classList.toggle("is-open");
        trigger.setAttribute("aria-expanded", String(isOpen));
      });
    });

    /* 2. Filtros por etapa histórica */
    function applyFilter(stage) {
      let visibleCount = 0;

      timelineItems.forEach((item) => {
        const matches = stage === "all" || item.dataset.stage === stage;
        item.classList.toggle("is-hidden", !matches);
        if (matches) visibleCount++;
      });

      if (statusCounter) {
        statusCounter.innerHTML =
          "Mostrando <strong>" + visibleCount + "</strong> de " + timelineItems.length +
          " hitos · Haz clic en cada hito para desplegarlo.";
      }
    }

    filterButtons.forEach((btn) => {
      bindAccessibleClick(btn, () => {
        filterButtons.forEach((b) => {
          b.classList.remove("is-active");
          b.setAttribute("aria-pressed", "false");
        });
        btn.classList.add("is-active");
        btn.setAttribute("aria-pressed", "true");
        applyFilter(btn.dataset.filter);
      });
    });

    /* 3. Expandir todo / Contraer todo */
    function setAllVisible(openState) {
      timelineItems.forEach((item) => {
        if (item.classList.contains("is-hidden")) return;
        item.classList.toggle("is-open", openState);
        const trigger = item.querySelector(".lt-card-trigger");
        if (trigger) {
          trigger.setAttribute("aria-expanded", String(openState));
        }
      });
    }

    bindAccessibleClick(expandAllBtn, () => setAllVisible(true));
    bindAccessibleClick(collapseAllBtn, () => setAllVisible(false));

    /* 4. Visor ampliado (Lightbox) para las 11 ilustraciones */
    function openLightbox(triggerEl) {
      const figure = triggerEl.closest("figure.lt-figure");
      if (!figure || !lightbox) return;

      const mediaNode = triggerEl.querySelector("svg, img");
      const captionNode = figure.querySelector("figcaption.lt-figcaption");
      if (!mediaNode) return;

      lastFocused = triggerEl;
      lightboxTitle.textContent = triggerEl.dataset.zoomTitle || "Ilustración histórica";
      lightboxMedia.innerHTML = "";
      lightboxMedia.appendChild(mediaNode.cloneNode(true));
      lightboxCaption.innerHTML = captionNode ? captionNode.innerHTML : "";

      lightbox.classList.add("is-visible");
      lightbox.setAttribute("aria-hidden", "false");
      if (lightboxClose) lightboxClose.focus();
    }

    function closeLightbox() {
      if (!lightbox) return;
      lightbox.classList.remove("is-visible");
      lightbox.setAttribute("aria-hidden", "true");
      if (lastFocused) lastFocused.focus();
    }

    root.querySelectorAll(".lt-zoom-trigger").forEach((triggerEl) => {
      bindAccessibleClick(triggerEl, () => openLightbox(triggerEl));
    });

    bindAccessibleClick(lightboxClose, closeLightbox);

    if (lightbox) {
      lightbox.addEventListener("click", (event) => {
        if (event.target === lightbox) closeLightbox();
      });
    }

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && lightbox && lightbox.classList.contains("is-visible")) {
        closeLightbox();
      }
    });
  })();
