<script>
(function() {
    function iniciarEscenaDominios() {
        const root = document.getElementById('dom-interactivo-naranja');
        if (!root) return;

        const canvas = document.getElementById('dom-canvas');
        const ctx = canvas.getContext('2d');
        const formulaEl = document.getElementById('dom-formula');
        const pistaEl = document.getElementById('dom-pista');
        const zonaInputs = document.getElementById('dom-zona-inputs');
        const subnotaEl = document.getElementById('dom-subnota');
        const feedbackEl = document.getElementById('dom-feedback');
        const btnOtra = document.getElementById('dom-btn-otra');
        const btnComprobar = document.getElementById('dom-btn-comprobar');
        const btnSolucion = document.getElementById('dom-btn-solucion');
        const btnsCaso = root.querySelectorAll('.dom-btn-caso');

        let casoActual = 1;
        let estado = {};

        const W = canvas.width;
        const H = canvas.height;
        const MIN = -10, MAX = 10;
        const toPxX = x => ((x - MIN) / (MAX - MIN)) * W;
        const toPxY = y => H - ((y - MIN) / (MAX - MIN)) * H;

        function randInt(min, max) {
            return Math.floor(Math.random() * (max - min + 1)) + min;
        }

        function formatoXmasK(k) {
            if (k === 0) return 'x';
            return k > 0 ? `x + ${k}` : `x − ${Math.abs(k)}`;
        }

        function dibujarEjes() {
            ctx.clearRect(0, 0, W, H);
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, W, H);

            ctx.strokeStyle = '#e2e8f0';
            ctx.lineWidth = 1;
            for (let i = MIN; i <= MAX; i++) {
                let px = Math.round(toPxX(i)) + 0.5;
                let py = Math.round(toPxY(i)) + 0.5;
                ctx.beginPath(); ctx.moveTo(px, 0); ctx.lineTo(px, H); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(0, py); ctx.lineTo(W, py); ctx.stroke();
            }

            const ox = Math.round(toPxX(0)) + 0.5;
            const oy = Math.round(toPxY(0)) + 0.5;
            ctx.strokeStyle = '#475569';
            ctx.lineWidth = 1.6;
            ctx.beginPath(); ctx.moveTo(0, oy); ctx.lineTo(W, oy); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(ox, 0); ctx.lineTo(ox, H); ctx.stroke();

            ctx.lineWidth = 1.2;
            for (let i = MIN; i <= MAX; i++) {
                if (i === 0) continue;
                let px = toPxX(i);
                let py = toPxY(i);
                let tick = (i % 5 === 0) ? 5 : 3;
                ctx.beginPath(); ctx.moveTo(px, oy - tick); ctx.lineTo(px, oy + tick); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(ox - tick, py); ctx.lineTo(ox + tick, py); ctx.stroke();
            }

            ctx.fillStyle = '#64748b';
            ctx.font = 'bold 12px Segoe UI, Arial, sans-serif';
            ctx.fillText('X', W - 14, oy + 16);
            ctx.fillText('Y', ox - 16, 15);
            ctx.fillText('0', ox + 4, oy - 5);
            ctx.fillText('-10', 4, oy - 6);
            ctx.fillText('10', W - 18, oy - 6);
            ctx.fillText('10', ox + 5, 13);
            ctx.fillText('-10', ox + 5, H - 5);
        }

        function dibujarAsintotaVertical(xVal) {
            const px = toPxX(xVal);
            ctx.save();
            ctx.strokeStyle = '#64748b';
            ctx.lineWidth = 1.4;
            ctx.setLineDash([5, 4]);
            ctx.beginPath();
            ctx.moveTo(px, 0);
            ctx.lineTo(px, H);
            ctx.stroke();
            ctx.restore();
        }

        function dibujarCurva(fn, xInicio, xFin, saltos) {
            ctx.save();
            ctx.strokeStyle = '#1d4ed8';
            ctx.lineWidth = 2.4;
            ctx.beginPath();
            let dibujando = false;
            const paso = 0.04;

            for (let x = xInicio; x <= xFin; x += paso) {
                let cercaSalto = saltos.some(s => Math.abs(x - s) < 0.06);
                if (cercaSalto) {
                    dibujando = false;
                    continue;
                }
                let y = fn(x);
                if (!isFinite(y) || isNaN(y) || y < MIN - 4 || y > MAX + 4) {
                    dibujando = false;
                    continue;
                }
                let px = toPxX(x);
                let py = toPxY(y);
                if (!dibujando) {
                    ctx.moveTo(px, py);
                    dibujando = true;
                } else {
                    ctx.lineTo(px, py);
                }
            }
            ctx.stroke();
            ctx.restore();
        }

        function dibujarDominioEnEjeX(tipo, valores) {
            const oy = toPxY(0);
            ctx.save();
            ctx.strokeStyle = '#ea580c';
            ctx.lineWidth = 3.5;

            if (tipo === 'todos-menos') {
                ctx.beginPath();
                ctx.moveTo(0, oy);
                ctx.lineTo(W, oy);
                ctx.stroke();

                valores.forEach(v => {
                    let px = toPxX(v);
                    ctx.fillStyle = '#ffffff';
                    ctx.strokeStyle = '#ea580c';
                    ctx.lineWidth = 2.5;
                    ctx.beginPath();
                    ctx.arc(px, oy, 5, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.stroke();

                    ctx.fillStyle = '#ea580c';
                    ctx.font = 'bold 14px Segoe UI, Arial, sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText(String(v), px, oy + 20);
                });
            } else if (tipo === 'semirrecta-cerrada' || tipo === 'semirrecta-abierta') {
                const v = valores[0];
                const px = toPxX(v);
                ctx.beginPath();
                ctx.moveTo(px, oy);
                ctx.lineTo(W, oy);
                ctx.stroke();

                ctx.fillStyle = (tipo === 'semirrecta-cerrada') ? '#ea580c' : '#ffffff';
                ctx.strokeStyle = '#ea580c';
                ctx.lineWidth = 2.5;
                ctx.beginPath();
                ctx.arc(px, oy, 5.5, 0, Math.PI * 2);
                ctx.fill();
                ctx.stroke();

                ctx.fillStyle = '#ea580c';
                ctx.font = 'bold 14px Segoe UI, Arial, sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText(String(v), px, oy + 20);
            }
            ctx.restore();
        }

        function renderizarGrafica(mostrarSolucion) {
            dibujarEjes();

            if (casoActual === 1) {
                const [r1, r2, r3] = estado.raices;
                estado.raices.forEach(dibujarAsintotaVertical);
                const fn = x => estado.escala / ((x - r1) * (x - r2) * (x - r3)) + estado.desplY;
                dibujarCurva(fn, MIN, MAX, estado.raices);
                if (mostrarSolucion) {
                    dibujarDominioEnEjeX('todos-menos', estado.raices);
                }
            } else if (casoActual === 2 && mostrarSolucion) {
                const a = -estado.k;
                dibujarAsintotaVertical(a);
                dibujarCurva(x => 1 / (x + estado.k), MIN, MAX, [a]);
                dibujarDominioEnEjeX('todos-menos', [a]);
            } else if (casoActual === 3 && mostrarSolucion) {
                const a = -estado.k;
                dibujarCurva(x => Math.sqrt(x + estado.k), a, MAX, []);
                dibujarDominioEnEjeX('semirrecta-cerrada', [a]);
            } else if (casoActual === 4 && mostrarSolucion) {
                const a = -estado.k;
                dibujarAsintotaVertical(a);
                dibujarCurva(x => 1 / Math.sqrt(x + estado.k), a + 0.01, MAX, [a]);
                dibujarDominioEnEjeX('semirrecta-abierta', [a]);
            }
        }

        function textoExplicacion() {
            if (casoActual === 1) {
                const [r1, r2, r3] = estado.raices;
                return `La función no tiene imagen en las asíntotas verticales x = ${r1}, x = ${r2} y x = ${r3}.`;
            } else if (casoActual === 2) {
                return `El denominador se anula cuando ${formatoXmasK(estado.k)} = 0, es decir, en x = ${estado.sol}. Por tanto, Dom f = ℝ − {${estado.sol}}.`;
            } else if (casoActual === 3) {
                return `El radicando debe cumplir ${formatoXmasK(estado.k)} ≥ 0, es decir, x ≥ ${estado.sol}. Por tanto, Dom f = [${estado.sol}, +∞).`;
            } else {
                return `El radicando está en el denominador, así que debe cumplir ${formatoXmasK(estado.k)} > 0, es decir, x > ${estado.sol}. Por tanto, Dom f = (${estado.sol}, +∞).`;
            }
        }

        function generarFuncion() {
            feedbackEl.className = 'dom-feedback';
            feedbackEl.innerHTML = '';
            btnSolucion.classList.remove('mostrar');

            if (casoActual === 1) {
                let r1, r2, r3;
                do {
                    r1 = randInt(-6, 1);
                    r2 = randInt(r1 + 2, 4);
                    r3 = randInt(r2 + 2, 6);
                } while (r3 > 6);

                const m1 = (r1 + r2) / 2;
                const d1 = Math.abs((m1 - r1) * (m1 - r2) * (m1 - r3));
                const escala = (Math.random() < 0.5 ? 1 : -1) * Math.max(4, Math.min(18, d1 * 2.8));
                const desplY = (Math.random() < 0.5 ? 1 : -1) * 1.2;

                estado = { raices: [r1, r2, r3], escala, desplY };

                formulaEl.innerHTML = 'y = f(x)';
                pistaEl.innerHTML = 'Observa la gráfica. ¿Todos los valores de <strong>x</strong> tienen imagen?';
                zonaInputs.innerHTML = `
                    <div class="dom-label" style="margin-bottom:8px;">Dom f = todos los reales excepto:</div>
                    <div style="display:flex; gap:10px; align-items:center;">
                        <input type="number" class="dom-input" id="dom-in-1" autocomplete="off">
                        <input type="number" class="dom-input" id="dom-in-2" autocomplete="off">
                        <input type="number" class="dom-input" id="dom-in-3" autocomplete="off">
                    </div>
                `;
                subnotaEl.innerHTML = 'Introdúcelos de menor a mayor y pulsa Comprobar.';
                renderizarGrafica(false);
            }
            else if (casoActual === 2) {
                let k;
                do { k = randInt(-6, 6); } while (k === 0);
                estado = { k, sol: -k };

                formulaEl.innerHTML = `
                    <span>f(x) =</span>
                    <div class="dom-frac">
                        <div class="dom-frac-num">1</div>
                        <div class="dom-frac-den">${formatoXmasK(k)}</div>
                    </div>
                `;
                pistaEl.innerHTML = '<strong>RECUERDA:</strong> El denominador no puede ser <strong>0</strong>.';
                zonaInputs.innerHTML = `
                    <div class="dom-label">
                        <span>Dom f = ℝ − {</span>
                        <input type="number" class="dom-input" id="dom-in-1" autocomplete="off">
                        <span>}</span>
                    </div>
                `;
                subnotaEl.innerHTML = 'Introduce el valor y pulsa INTRO o Comprobar.';
                renderizarGrafica(false);
            }
            else if (casoActual === 3) {
                const k = randInt(-6, 6);
                estado = { k, sol: -k };

                formulaEl.innerHTML = `
                    <span>f(x) =</span>
                    <div class="dom-sqrt">
                        <span class="dom-sqrt-sym">√</span>
                        <span class="dom-sqrt-rad">${formatoXmasK(k)}</span>
                    </div>
                `;
                pistaEl.innerHTML = '<strong>RECUERDA:</strong> El radicando ha de ser <strong>≥ 0</strong>.';
                zonaInputs.innerHTML = `
                    <div class="dom-label">
                        <span>Dom f = [</span>
                        <input type="number" class="dom-input" id="dom-in-1" autocomplete="off">
                        <span>, +∞ )</span>
                    </div>
                `;
                subnotaEl.innerHTML = 'Introduce el valor y pulsa INTRO o Comprobar.';
                renderizarGrafica(false);
            }
            else if (casoActual === 4) {
                const k = randInt(-6, 6);
                estado = { k, sol: -k };

                formulaEl.innerHTML = `
                    <span>f(x) =</span>
                    <div class="dom-frac">
                        <div class="dom-frac-num">1</div>
                        <div class="dom-frac-den">
                            <div class="dom-sqrt">
                                <span class="dom-sqrt-sym">√</span>
                                <span class="dom-sqrt-rad">${formatoXmasK(k)}</span>
                            </div>
                        </div>
                    </div>
                `;
                pistaEl.innerHTML = '<strong>RECUERDA:</strong> El radicando está en el denominador, por lo que ha de ser <strong>&gt; 0</strong>.';
                zonaInputs.innerHTML = `
                    <div class="dom-label">
                        <span>Dom f = (</span>
                        <input type="number" class="dom-input" id="dom-in-1" autocomplete="off">
                        <span>, +∞ )</span>
                    </div>
                `;
                subnotaEl.innerHTML = 'Introduce el valor y pulsa INTRO o Comprobar.';
                renderizarGrafica(false);
            }

            root.querySelectorAll('.dom-input').forEach(inp => {
                inp.addEventListener('keydown', e => {
                    if (e.key === 'Enter') comprobar();
                });
            });
            const primerInput = document.getElementById('dom-in-1');
            if (primerInput) primerInput.focus();
        }

        function comprobar() {
            if (casoActual === 1) {
                const v1 = parseInt(document.getElementById('dom-in-1').value, 10);
                const v2 = parseInt(document.getElementById('dom-in-2').value, 10);
                const v3 = parseInt(document.getElementById('dom-in-3').value, 10);
                const [r1, r2, r3] = estado.raices;

                if (v1 === r1 && v2 === r2 && v3 === r3) {
                    feedbackEl.className = 'dom-feedback ok';
                    feedbackEl.innerHTML = `¡Correcto! ${textoExplicacion()}`;
                    btnSolucion.classList.remove('mostrar');
                    renderizarGrafica(true);
                } else {
                    feedbackEl.className = 'dom-feedback err';
                    feedbackEl.innerHTML = 'Revisa los valores de x donde aparecen las asíntotas verticales y asegúrate de escribirlos de menor a mayor.';
                    btnSolucion.classList.add('mostrar');
                }
            } else {
                const v = parseInt(document.getElementById('dom-in-1').value, 10);
                if (v === estado.sol) {
                    feedbackEl.className = 'dom-feedback ok';
                    feedbackEl.innerHTML = `¡Correcto! ${textoExplicacion()} Observa la gráfica.`;
                    btnSolucion.classList.remove('mostrar');
                    renderizarGrafica(true);
                } else {
                    feedbackEl.className = 'dom-feedback err';
                    feedbackEl.innerHTML = 'Incorrecto. Revisa el signo al despejar la x o pulsa «Ver solución».';
                    btnSolucion.classList.add('mostrar');
                }
            }
        }

        function verSolucion() {
            if (casoActual === 1) {
                document.getElementById('dom-in-1').value = estado.raices[0];
                document.getElementById('dom-in-2').value = estado.raices[1];
                document.getElementById('dom-in-3').value = estado.raices[2];
            } else {
                document.getElementById('dom-in-1').value = estado.sol;
            }
            feedbackEl.className = 'dom-feedback info';
            feedbackEl.innerHTML = `<strong>Solución:</strong> ${textoExplicacion()}`;
            btnSolucion.classList.remove('mostrar');
            renderizarGrafica(true);
        }

        btnsCaso.forEach(btn => {
            btn.addEventListener('click', () => {
                btnsCaso.forEach(b => b.classList.remove('activo'));
                btn.classList.add('activo');
                casoActual = parseInt(btn.getAttribute('data-caso'), 10);
                generarFuncion();
            });
        });

        btnOtra.addEventListener('click', generarFuncion);
        btnComprobar.addEventListener('click', comprobar);
        btnSolucion.addEventListener('click', verSolucion);

        generarFuncion();
    }

    setTimeout(iniciarEscenaDominios, 100);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
